'use strict';
let europeProbeScenario='season';
function renderEuropeProbe(f,eventLinks){
 if(!f.probe_scenarios)return '';
 const selected=f.probe_scenarios.find(s=>s.id===europeProbeScenario)||f.probe_scenarios[0];
 return `<section class="europe-probe" data-probe-focus="${esc(f.region_key||'europe_focus')}" aria-label="elección del país por el propósito de la familia"><p class="section-kicker">TRES PAÍSES · DISTINTOS OBJETIVOS</p><h4>¿Qué quieres obtener de un viaje?</h4><p class="audit-footnote">mi evaluación de la conformidad de su familia. elige un objetivo: las recomendaciones cambian; el programa publicado no confirma el lugar.</p><div class="europe-probe-tabs" role="group" aria-label="el objetivo del viaje">${f.probe_scenarios.map(s=>`<button type="button" data-europe-probe="${esc(s.id)}" aria-pressed="${s.id===selected.id}">${esc(s.label)}</button>`).join('')}</div><div aria-live="polite"><p>${esc(selected.intro)}</p><div class="europe-shortlist-grid">${selected.countries.map(c=>`<article data-europe-probe-country="${esc(c.iso)}"><p class="section-kicker">${esc(DATA.countries.find(x=>x.iso===c.iso).country)}</p><h5>${esc(c.verdict)}</h5><p>${esc(c.reason)}</p><p class="audit-footnote">${esc(c.gate)}</p><div class="taiwan-route-links">${eventLinks(c.event_ids)}${c.school_ids.map(id=>`<button data-europe-school="${esc(id)}">${esc(DATA.schools.find(s=>s.id===id).name)} · dossier ↗</button>`).join('')}</div></article>`).join('')}</div></div><details class="europe-options"><summary>el rumbo a 10–12 años: habilidades, ingeniería y su producto</summary><p class="audit-footnote">No hay garantías de fechas futuras, reglas de la liga y victorias.</p>${f.development_phases.map(c=>`<article><h5>${esc(c.period)} · ${esc(c.title)}</h5><p>${esc(c.detail)}</p></article>`).join('')}</details></section>`;
}
document.addEventListener('click',event=>{
 const b=event.target.closest('[data-europe-probe]');if(!b)return;
 europeProbeScenario=b.dataset.europeProbe;
 const eventLinks=ids=>ids.map(id=>{const e=EVENTS.find(e=>e.id===id);return e?`<button data-open="${esc(id)}">${esc(e.title)} ↗</button>`:''}).join('');
 const panel=b.closest('.europe-probe'),focus=DATA[panel.dataset.probeFocus||'europe_focus'];
 panel.outerHTML=renderEuropeProbe(focus,eventLinks);
 document.querySelector(`[data-europe-probe="${europeProbeScenario}"]`)?.focus({preventScroll:true});
});
function renderEuropeFamilyPicks(f,eventLinks){
 if(!f.family_picks)return '';
 return `<section class="europe-shortlist europe-family-picks" aria-label="las mejores opciones para su familia"><p class="section-kicker">SELECCIÓN PARA MATVEY Y OSCAR · VERIFICACIÓN 02.10.2026</p><h4>${esc(f.family_picks_heading||"¿De dónde empezaría en estos tres países?")}</h4><p class="audit-footnote">${esc(f.family_picks_note)}</p><label>Mostrar <select id="europe-pick-filter"><option value="all">todas las opciones</option>${Object.entries({league:"competiciones y ligas",camp:"campo y prueba corta",school:"escuelas permanentes"}).filter(([kind])=>f.family_picks.some(c=>c.kind===kind)).map(([kind,label])=>`<option value="${kind}">${label}</option>`).join('')}</select></label><div class="europe-shortlist-grid">${f.family_picks.map(c=>`<details class="europe-options" data-europe-pick-kind="${esc(c.kind)}"><summary>${esc(c.country)} · ${esc(c.title)}</summary><p>${esc(c.why)}</p><p class="audit-footnote">${esc(c.gate)}</p><div class="taiwan-route-links">${eventLinks(c.event_ids)}${c.school_ids.map(id=>`<button data-europe-school="${esc(id)}">${esc(DATA.schools.find(s=>s.id===id).name)} · dossier ↗</button>`).join('')}</div><div class="europe-source-links">${c.source_urls.map((url,i)=>`<a href="${esc(url)}" target="_blank" rel="noopener">fuente primaria ${i+1} ↗</a>`).join('')}</div></details>`).join('')}</div></section>`;
}
document.addEventListener('change',event=>{
 if(event.target.id==='europe-pick-filter')document.querySelectorAll('[data-europe-pick-kind]').forEach(card=>{card.hidden=event.target.value!=='all'&&card.dataset.europePickKind!==event.target.value;});
});
function renderEuropeBaseComparison(f,eventLinks){
 if(!f.base_comparison)return '';
 return `<section class="europe-base-comparison" aria-label="comparación de tres países para su familia"><p class="section-kicker">MI SELECCIÓN · DOS EDADES Y TRES PAÍSES</p><h4>¿Dónde empezaría para su familia?</h4><p class="audit-footnote">${esc(f.comparison_note)}</p><div class="europe-decision-grid">${f.base_comparison.map((c,i)=>`<details class="europe-decision" data-europe-base="${esc(c.iso)}" ${i===0?'open':''}><summary><span>${esc(c.country)}</span><strong>${esc(c.label)}</strong><small>niños, escuela, presupuesto y prueba ↓</small></summary><div><p>${esc(c.conclusion)}</p><dl>${[["Matvey",c.mat],["Oscar",c.osc],["escuela",c.school],["ejemplo del presupuesto",c.budget],["¿Cómo probarlo?",c.trial],["condiciones de participación",c.gate]].map(([label,value])=>`<dt>${label}</dt><dd>${esc(value)}</dd>`).join('')}</dl><div class="taiwan-route-links">${eventLinks(c.event_ids)}${c.school_ids.map(id=>`<button data-europe-school="${esc(id)}">${esc(DATA.schools.find(s=>s.id===id).name)} · dossier ↗</button>`).join('')}</div><div class="europe-source-links">${c.source_urls.map((url,j)=>`<a href="${esc(url)}" target="_blank" rel="noopener">fuente primaria ${j+1} ↗</a>`).join('')}</div></div></details>`).join('')}</div></section>`;
}
function renderEuropeDecisionBlocks(f,eventLinks){
 if(!f.decisions)return '';
 return `<section class="europe-decisions" aria-label="la elección de la ruta familiar"><p class="section-kicker">TU OBJETIVO · COMPARAR OPCIONES</p><h4>donde vivir, entrenar y probar</h4><p class="audit-footnote">${esc(f.decision_note)}</p><div class="europe-decision-grid">${f.decisions.map((c,i)=>`<details class="europe-decision" data-europe-decision="${esc(c.id)}" ${i===0?'open':''}><summary><span>${esc(c.country)}</span><strong>${esc(c.title)}</strong><small>abrir las condiciones y el rumbo ↓</small></summary><div><p>${esc(c.conclusion)}</p><dl><dt>Matvey</dt><dd>${esc(c.mat)}</dd><dt>Oscar</dt><dd>${esc(c.osc)}</dd><dt>que se requiere confirmar</dt><dd>${esc(c.gate)}</dd></dl><div class="taiwan-route-links">${eventLinks(c.event_ids)}</div><div class="europe-source-links">${c.source_urls.map((url,j)=>`<a href="${esc(url)}" target="_blank" rel="noopener">fuente primaria ${j+1} ↗</a>`).join('')}</div></div></details>`).join('')}</div></section><section class="europe-age-routes" aria-label="el recorrido por edad 2026–2030"><p class="section-kicker">2026 → 2030 · DOS PARTICIPANTES AUTÓNOMOS</p><h4>cuando los hermanos pueden estar en una misma categoría</h4><p class="audit-footnote">${esc(f.age_route_note)}</p><div class="europe-age-grid">${f.age_routes.map(r=>`<details data-europe-year="${r.year}" ${r.year===2028?'open':''}><summary><strong>${r.year}</strong><span>Matvey · ${r.mat_age}</span><span>Oscar · ${r.osc_age}</span><small>el rumbo ↓</small></summary><div><dl><dt>Matvey</dt><dd>${esc(r.mat)}</dd><dt>Oscar</dt><dd>${esc(r.osc)}</dd><dt>¿Un equipo?</dt><dd>${esc(r.together)}</dd></dl><p>${esc(r.technical)}</p></div></details>`).join('')}</div></section><section class="europe-selection"><h4>Cómo elegir un maestro y una escuela</h4><div>${f.selection_checks.map(c=>`<article><h5>${esc(c.title)}</h5><p>${esc(c.detail)}</p></article>`).join('')}</div></section>`;
}
function renderEuropeFocus(box,count,f=DATA.europe_focus,downloadName='STEM_Europe_CHE_ESP_FRA'){
 if(!f){box.innerHTML='';return;}
 const countries=f.countries;
 const totals=countries.map(c=>({c,rows:EVENTS.filter(e=>e.iso.includes(c.iso))}));
 count.textContent=totals.map(({c,rows})=>c.name+' · '+rows.length+" fichas").join(' / ')+" · la verificación parcial";
 const eventLinks=ids=>ids.map(id=>{const e=EVENTS.find(e=>e.id===id);return e?`<button data-open="${esc(id)}">${esc(e.title)} ↗</button>`:''}).join('');
 const baseComparison=renderEuropeBaseComparison(f,eventLinks);
 const familyPicks=renderEuropeFamilyPicks(f,eventLinks);
 const probe=renderEuropeProbe(f,eventLinks);
 const seasonStops=f.season_stops?`<section class="europe-shortlist" aria-label="las nuevas fechas de temporada"><p class="section-kicker">${esc(f.season_kicker||"2026 / 2027 · ETAPAS PRESENCIALES Y VIAJES EN FAMILIA")}</p><h4>fechas de inicio de la planificación</h4><p class="audit-footnote">La fecha del evento, el lugar vacante, la lengua y el derecho de participación se comprueban por separado.</p><div class="europe-shortlist-grid">${f.season_stops.map((s,i)=>`<details class="europe-options" data-europe-stop="${i}"><summary>${esc(s.date)} · ${esc(s.title)}</summary><p class="section-kicker">${esc(s.country)}</p><p>${esc(s.detail)}</p><div class="taiwan-route-links">${eventLinks(s.event_ids)}</div></details>`).join('')}</div></section>`:'';
 const decisionBlocks=renderEuropeDecisionBlocks(f,eventLinks);
 const evidenceBlocks=f.evidence_cards?`<section class="europe-shortlist" aria-label="resultados de los equipos y condiciones de los programas menores"><p class="section-kicker">VERIFICADO · EQUIPO, COLEGIO E IDIOMA</p><h4>que confirman los resultados reales</h4><p class="audit-footnote">El laboratorio y la escuela de inglés requieren una verificación separada del tutor menor.</p><div class="europe-shortlist-grid">${f.evidence_cards.map((c,i)=>`<details class="europe-options" data-europe-evidence="${i}"><summary>${esc(c.title)}</summary><p>${esc(c.detail)}</p><p class="audit-footnote">${esc(c.limit)}</p><div class="taiwan-route-links">${eventLinks(c.event_ids)}${c.school_ids.map(id=>`<button data-europe-school="${esc(id)}">${esc(DATA.schools.find(s=>s.id===id).name)} · dossier ↗</button>`).join('')}</div><div class="europe-source-links">${c.source_urls.map((url,j)=>`<a href="${esc(url)}" target="_blank" rel="noopener">fuente primaria ${j+1} ↗</a>`).join('')}</div></details>`).join('')}</div></section>`:'';
 const shortlist=f.shortlist?`<section class="europe-shortlist"><p class="section-kicker">PRIMEROS PASOS · PARA TU FAMILIA</p><h4>¿Qué es lo que primero debemos comprobar?</h4><div class="europe-shortlist-grid">${f.shortlist.map(s=>`<article><h5>${esc(s.title)}</h5><p>${esc(s.detail)}</p><div class="taiwan-route-links">${eventLinks(s.event_ids)}</div></article>`).join('')}</div></section>`:'';
 const deeper=c=>[["ciudad para el período de prueba",c.city_route],["precio y horario técnico",c.budget],["lo que se ha demostrado sobre los resultados",c.results_check]].filter(([,v])=>v).map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join('');
 box.innerHTML=`<div class="taiwan-intro europe-intro"><p class="section-kicker">${esc(f.region_label||"EUROPA · EDAD, IDIOMA Y VÍA DE CLASIFICACIÓN")}</p><h4>${f.heading?esc(f.heading):"tres países.<br>El camino que se va a cada niño."}</h4><p>${esc(f.family)}</p><p>${esc(f.conclusion)}</p><div class="taiwan-route-links">${totals.map(({c,rows})=>`<button class="button secondary" data-country-catalog="${esc(c.iso)}">${esc(c.name)} · todos ${rows.length} →</button>`).join('')}</div></div>${probe}${familyPicks}${baseComparison}${seasonStops}${decisionBlocks}${evidenceBlocks}${shortlist}<div class="taiwan-routes europe-routes${countries.length===2?' two-countries':countries.length===4?' four-countries':''}">${countries.map((c,i)=>`<article data-europe-country="${esc(c.iso)}"><span class="audit-index">${String(i+1).padStart(2,'0')}</span><p class="section-kicker">${esc(c.verdict)}</p><h4>${esc(c.name)}</h4><p>${esc(c.reason)}</p><dl><dt>Matvey · 2017</dt><dd>${esc(c.mat)}</dd><dt>Oscar · 2020</dt><dd>${esc(c.osc)}</dd><dt>campamentos y vacaciones</dt><dd>${esc(c.camp)}</dd><dt>escuela permanente</dt><dd>${esc(c.school)}</dd>${deeper(c)}</dl><p class="audit-footnote">${esc(c.risk)}</p><div class="taiwan-route-links">${c.profile_ids.map(id=>`<button data-audit-league="${esc(id)}">las reglas · ${esc(DATA.league_guide.profiles.find(p=>p.id===id).name)} ↗</button>`).join('')}${c.school_ids.map(id=>`<button data-europe-school="${esc(id)}">${esc(DATA.schools.find(s=>s.id===id).name)} · dossier ↗</button>`).join('')}</div><details class="europe-options"><summary>competiciones, campamentos y exposiciones · ${c.event_ids.length} de las tarjetas clave</summary><div class="taiwan-route-links">${eventLinks(c.event_ids)}</div></details></article>`).join('')}</div><div class="europe-plan"><h4>Cómo comprobar el rumbo antes de mudarse</h4>${f.steps.map((s,i)=>`<article><span class="audit-index">${i+1}</span><div><h5>${esc(s.title)}</h5><p>${esc(s.detail)}</p></div></article>`).join('')}</div><p class="audit-footnote">${esc(f.limitations)}</p><details class="audit-boundaries"><summary>fuentes primarias leídas</summary>${f.sources.map(s=>`<p><a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.title)} ↗</a> · ${esc(s.checked)}</p>`).join('')}</details><div class="audit-downloads"><a class="button secondary" href="downloads/${esc(downloadName)}.md" download>informe por país ↓</a><a class="button secondary" href="downloads/${esc(downloadName)}.json" download>datos por países ↓</a></div>`;
}
document.addEventListener('click',event=>{
 const b=event.target.closest('button');if(!b)return;
 if(b.hasAttribute('data-europe-open')){auditState.tab='europe';auditState.query='';setView('about');history.replaceState(null,'','#europe');requestAnimationFrame(()=>document.querySelector('.europe-intro')?.scrollIntoView({block:'start'}));}
 if(b.hasAttribute('data-north-europe-open')){auditState.tab='europe-north';auditState.query='';setView('about');history.replaceState(null,'','#europe-north');requestAnimationFrame(()=>document.querySelector('.europe-intro')?.scrollIntoView({block:'start'}));}
 if(b.hasAttribute('data-south-europe-open')){auditState.tab='europe-south';auditState.query='';setView('about');history.replaceState(null,'','#europe-south');requestAnimationFrame(()=>document.querySelector('.europe-intro')?.scrollIntoView({block:'start'}));}
 if(b.hasAttribute('data-east-asia-open')){auditState.tab='eastasia';auditState.query='';setView('about');history.replaceState(null,'','#eastasia');requestAnimationFrame(()=>document.querySelector('.europe-intro')?.scrollIntoView({block:'start'}));}
 if(b.hasAttribute('data-asia-english-open')){auditState.tab='asia-english';auditState.query='';setView('about');history.replaceState(null,'','#asia-english');requestAnimationFrame(()=>document.querySelector('.europe-intro')?.scrollIntoView({block:'start'}));}
 if(b.hasAttribute('data-southeast-asia-open')){auditState.tab='southeastasia';auditState.query='';setView('about');history.replaceState(null,'','#southeastasia');requestAnimationFrame(()=>document.querySelector('.europe-intro')?.scrollIntoView({block:'start'}));}
 if(b.hasAttribute('data-middleeast-open')){auditState.tab='middleeast';auditState.query='';setView('about');history.replaceState(null,'','#middleeast');requestAnimationFrame(()=>document.querySelector('.europe-intro')?.scrollIntoView({block:'start'}));}
 if(b.hasAttribute('data-africa-open')){auditState.tab='africa';auditState.query='';setView('about');history.replaceState(null,'','#africa');requestAnimationFrame(()=>document.querySelector('.europe-intro')?.scrollIntoView({block:'start'}));}
 if(b.dataset.europeSchool)window.openAtlasSchool(b.dataset.europeSchool);
});
